const dict: Record<Lang, typeof en> = { en, sr };
export type Key = keyof typeof en;

const langOf = new WeakMap<(k: Key) => string, Lang>();

export function makeT(lang: Lang) {
  const t = (k: Key): string => dict[lang][k] ?? dict.en[k] ?? k;
  langOf.set(t, lang);
  return t;
}

/** The language a `t` from makeT speaks. */
export function tLang(t: (k: Key) => string): Lang {
  return langOf.get(t) ?? "en";
}
